let signup=false,busy=false;const $=id=>document.getElementById(id);
function setMode(value){if(busy)return;signup=value;$('title').textContent=signup?'Create your account':'Welcome back';$('intro').textContent=signup?'Create an account for this shared voice assistant.':'Sign in to your voice assistant.';$('password').autocomplete=signup?'new-password':'current-password';$('confirmField').hidden=!signup;$('confirmPassword').required=signup;$('password').value='';$('confirmPassword').value='';$('submit').textContent=signup?'Create account':'Sign in';$('signInTab').className=signup?'quiet':'';$('signUpTab').className=signup?'':'quiet';$('signInTab').setAttribute('aria-pressed',String(!signup));$('signUpTab').setAttribute('aria-pressed',String(signup));$('feedback').textContent='';}
$('signInTab').onclick=()=>setMode(false);$('signUpTab').onclick=()=>setMode(true);
fetch('/api/auth/status').then(r=>r.json()).then(d=>{$('loggedInUser').value=(d.username||'').toUpperCase();if(d.authenticated){location.replace('/');return}$('submit').disabled=false}).catch(()=>{$('feedback').textContent='Unable to connect. Refresh to retry.'});
$('loginForm').onsubmit=async e=>{e.preventDefault();if(busy)return;if(signup&&$('password').value!==$('confirmPassword').value){$('feedback').textContent='Passwords do not match.';return}busy=true;$('submit').disabled=true;$('feedback').textContent='';try{const r=await fetch(signup?'/api/auth/signup':'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('username').value,password:$('password').value})});const d=await r.json();if(!r.ok)throw Error(d.error);location.replace('/')}catch(err){$('feedback').textContent=err.message;}finally{busy=false;$('submit').disabled=false}};
